use std::io::{BufRead, BufReader, Read, Write};
use std::net::{SocketAddr, TcpListener, TcpStream};
use std::thread;
use std::time::{Duration, Instant};

fn handle_connection(mut stream: TcpStream) {
    let request: Vec<String> = BufReader::new(&stream)
        .lines()
        .map(|l| l.unwrap())
        .take_while(|l| !l.is_empty())
        .collect();
    let body = match &request[0][..] {
        "GET /sleep HTTP/1.1" => {
            thread::sleep(Duration::from_millis(500));
            "slept"
        }
        _ => "hello",
    };
    write!(stream, "HTTP/1.1 200 OK\r\nContent-Length: {}\r\n\r\n{body}", body.len()).unwrap();
}

fn timed_get(addr: SocketAddr, path: &str) -> Duration {
    let start = Instant::now();
    let mut s = TcpStream::connect(addr).unwrap();
    write!(s, "GET {path} HTTP/1.1\r\n\r\n").unwrap();
    s.read_to_string(&mut String::new()).unwrap();
    start.elapsed()
}

fn run(thread_per_connection: bool) -> Duration {
    let listener = TcpListener::bind("127.0.0.1:0").unwrap();
    let addr = listener.local_addr().unwrap();
    let server = thread::spawn(move || {
        let mut handles = Vec::new();
        for stream in listener.incoming().take(2) {
            let stream = stream.unwrap();
            if thread_per_connection {
                handles.push(thread::spawn(move || handle_connection(stream)));
            } else {
                handle_connection(stream);
            }
        }
        for h in handles {
            h.join().unwrap();
        }
    });
    let slow = thread::spawn(move || timed_get(addr, "/sleep"));
    thread::sleep(Duration::from_millis(50)); // let /sleep arrive first
    let fast = timed_get(addr, "/");
    slow.join().unwrap();
    server.join().unwrap();
    fast
}

fn main() {
    let t = run(false);
    println!("one thread: / took more than 300 ms: {}", t > Duration::from_millis(300));
    let t = run(true);
    println!("thread per connection: / took less than 200 ms: {}", t < Duration::from_millis(200));
}

let listener = TcpListener::bind("127.0.0.1:7878").unwrap();
let pool = ThreadPool::new(4);

for stream in listener.incoming() {
    let stream = stream.unwrap();
    pool.execute(|| {
