struct Worker {
    id: usize,
    thread: thread::JoinHandle<()>,
}

impl Worker {
    fn new(id: usize, receiver: Arc<Mutex<mpsc::Receiver<Job>>>) -> Worker {
        let thread = thread::spawn(move || loop {
            let Ok(job) = receiver.lock().unwrap().recv() else {
                break; // the pool is gone (lesson 3)
            };
            job();
        });
        Worker { id, thread }
    }
}

fn main() {
    let pool = ThreadPool::new(3);
    let (tx, rx) = mpsc::channel();
    let start = Instant::now();
    for n in 0..6 {
        let tx = tx.clone();
        pool.execute(move || {
            thread::sleep(Duration::from_millis(100));
            tx.send((n, thread::current().id())).unwrap();
        });
    }
    drop(tx);

    let mut results: Vec<_> = rx.iter().collect();
    let elapsed = start.elapsed();
    results.sort_by_key(|&(n, _)| n);
    let threads: HashSet<_> = results.iter().map(|&(_, id)| id).collect();
    println!("jobs finished: {:?}", results.iter().map(|&(n, _)| n).collect::<Vec<_>>());
    println!("threads used: {}", threads.len());
    println!("about 200 ms instead of 600: {}", elapsed < Duration::from_millis(450));
}

use std::sync::{Arc, Mutex, mpsc};
use std::thread;
use std::time::{Duration, Instant};

type Job = Box<dyn FnOnce() + Send + 'static>;

fn spawn_worker(receiver: Arc<Mutex<mpsc::Receiver<Job>>>) -> thread::JoinHandle<()> {
    thread::spawn(move || {
        // BUG: the MutexGuard from lock() lives until the end of the loop body
        while let Ok(job) = receiver.lock().unwrap().recv() {
            job();
        }
    })
}

fn main() {
    let (sender, receiver) = mpsc::channel::<Job>();
    let receiver = Arc::new(Mutex::new(receiver));
    let workers: Vec<_> = (0..4).map(|_| spawn_worker(Arc::clone(&receiver))).collect();

    let start = Instant::now();
    for _ in 0..4 {
        sender.send(Box::new(|| thread::sleep(Duration::from_millis(200)))).unwrap();
    }
    drop(sender);
    for w in workers {
        w.join().unwrap();
    }
    let fast = start.elapsed() < Duration::from_millis(500);
    println!("4 jobs of 200 ms took less than 500 ms: {fast}");
}
